entries[454016] = { ["name"] = "Funke der Magi", ["text"] = "100 Meter Reichweite\n[ Netherflux : Euer 'Netherflux' / Eure 'Berührung der Magi'] beschwört nun auch 12 Sek. lang einen Funken des Potenzials, wodurch der Schaden Eures nächsten Einsatzes von 'Arkanbeschuss', 'Arkanschlag' und 'Arkane Geschosse' ein Echo erzeugt, das 100% des Schadens verursacht.\n\nNachdem der Funke Schaden von allen drei Zaubern erhalten hat, explodiert er und fügt dabei allen Gegnern in der Nähe (400% der Zaubermacht) Arkanschaden zu." }
entries[454019] = { ["name"] = "Toxinnova", ["text"] = "Unbegrenzte Reichweite\nSofort\nAnsurek entfesselt einen Ring aus Gift, der Spielercharakteren innerhalb von 8 Metern 28781576 Naturschaden zufügt.\n\nDer Ring breitet sich aus, fügt Spielercharakteren, die ihn berühren, 15 Sek. lang alle 0.5 Sek. 2014710 Naturschaden zu und verlangsamt sie um 60%.\n\n' Reaktionsdampf ' bildet sich, wenn der Ring in Kontakt mit ' Reaktiver Schaum ' kommt." }
