entries[454341] = { ["name"] = "Ohrenbetäubendes Kreischen", ["text"] = "Wirken in 2.5 sek.\nKraas gibt ein lautes Kreischen von sich, das bei allen Spielercharakteren Schalleruptionen erzeugt und ihnen 2908563 Naturschaden zufügt.\n\nDieser Effekt unterbricht das Wirken von Zaubern und bringt alle so unterbrochenen Spielercharaktere 6 Sek. lang zum Schweigen." }
