entries[454349] = { ["name"] = "Glücksbringer der Flamme", ["text"] = "5 Meter Reichweite\nWirken in 1 sek.\nCa. 8 Procs pro Minute\nErfüllt Euch mit der Heiligen Flamme, sodass Eure Angriffe und Fähigkeiten gelegentlich einen Elementar des Lichts erschaffen, der Zielen 3 Heiligschaden zufügt.\n\nVerwendbar in Blüte des Lichts und nahen Schlüsselflammengebieten." }
entries[454350] = { ["name"] = "Giftiger Regen", ["text"] = "Sofort\nStrangspinnerin Takazj entfesselt einen entropischen Schlag, der zuerst 17268945 Schattenschaden und anschließend 10 Sek. lang alle 1 Sek. 1153301 Schattenschaden verursacht." }
entries[454351] = { ["name"] = "Zornige Vergeltung", ["text"] = "Sofort\nRuft das Licht an, um zu einem Avatar der Vergeltung zu werden. ['Richturteil' erzeugt zusätzlich 1 Heilige Kraft.][Jede verbrauchte Heilige Kraft lässt Euch in heiliges Licht aufgehen, das Gegnern in der Nähe (13.5% der Angriffskraft) Schaden zufügt.][Verringert die Abklingzeit von 'Heiliger Schock' um 50%.] [ Hammer des Zorns : 'Hammer des Zorns' kann gegen jedes beliebige Ziel eingesetzt werden ] Erhöht Euren Schaden und Eure Heilung 8 Sek. lang um 20%. [ Zornige Vergeltung : Aktiviert zusätzlich alle für 'Zornige Vergeltung' gelernten Effekte für 8 Sek / Erhöht Eure kritische Trefferchance 8 Sek. lang um 20%. ]" }
