entries[454383] = { ["name"] = "Donnerndes Schmettern", ["text"] = "40 Meter Reichweite\nSofort 6 sek. Abklingzeit\nDer Zaubernde springt zu einem zufälligen Spielercharakter, fügt Spielercharaktern innerhalb von 5 Metern des Einschlags körperlichen Schaden zu und betäubt sie für 3 Sek." }
