entries[454387] = { ["name"] = "Ingenieurskunstabklingzeiten zurücksetzen", ["text"] = "Wirken in 2 sek.\nSetzt die Abklingzeit der Ingenieurskunst von Khaz Algar zurück.\n\nDieser Gegenstand dient ausschließlich Testzwecken." }
entries[454388] = { ["name"] = "Explosion", ["text"] = "10 Meter Reichweite\nWirken in 2.25 sek.\nHerzsenger bricht beim Tod aus und fügt Spielercharakteren innerhalb von 12 Metern 0 Feuerschaden sowie zusätzlich 8 Sek. lang alle 2 Sek. 3 Feuerschaden zu." }
entries[454389] = { ["name"] = "Weißsträhne beschwören", ["text"] = "Sofort\nBeim Verbrauchen von Runen habt Ihr die Chance, 10 Sek. lang die Hilfe eines Reiters zu erhalten.\n\nMograine\nWirkt 'Tod und Verfall' an seiner Position. Der Effektbereich folgt seiner Bewegung.\n\nWeißsträhne\nWirkt 'Untot' auf Euer Ziel, was 24 Sek. lang alle 3 Sek. pro Stapel (9.15376% der Angriffskraft) Schattenfrostschaden verursacht. Wann immer 'Untot' Schaden verursacht, wird das Ziel mit einem weiteren Stapel belegt. Kann nicht erneuert werden.\n\nTrollbann\nWirkt 'Eisketten' auf Euer Ziel, was 8 Sek. lang dessen Bewegungsgeschwindigkeit um 40% verringert und den Schaden, den Ihr ihm zufügt, um 5% erhöht.\n\nNazgrim\nWährend Nazgrim aktiv ist, erhaltet Ihr 'Apokalyptische Eroberung', was Eure Stärke um 5% erhöht." }
entries[454390] = { ["name"] = "Trollbann beschwören", ["text"] = "Sofort\nBeim Verbrauchen von Runen habt Ihr die Chance, 10 Sek. lang die Hilfe eines Reiters zu erhalten.\n\nMograine\nWirkt 'Tod und Verfall' an seiner Position. Der Effektbereich folgt seiner Bewegung.\n\nWeißsträhne\nWirkt 'Untot' auf Euer Ziel, was 24 Sek. lang alle 3 Sek. pro Stapel (9.15376% der Angriffskraft) Schattenfrostschaden verursacht. Wann immer 'Untot' Schaden verursacht, wird das Ziel mit einem weiteren Stapel belegt. Kann nicht erneuert werden.\n\nTrollbann\nWirkt 'Eisketten' auf Euer Ziel, was 8 Sek. lang dessen Bewegungsgeschwindigkeit um 40% verringert und den Schaden, den Ihr ihm zufügt, um 5% erhöht.\n\nNazgrim\nWährend Nazgrim aktiv ist, erhaltet Ihr 'Apokalyptische Eroberung', was Eure Stärke um 5% erhöht." }
entries[454391] = { ["name"] = "Unbegrenzte Macht", ["text"] = "Elementar\nDer Verbrauch von Mahlstrom gewährt Euch 15 Sek. lang 1% Tempo.\n\nMehrere Anwendungen können sich überschneiden.\n\nVerstärkung\nDer Verbrauch von Mahlstromwaffenstapeln gewährt Euch 15 Sek. lang 1% Tempo.\n\nMehrere Anwendungen können sich überschneiden." }
entries[454392] = { ["name"] = "Nazgrim beschwören", ["text"] = "Sofort\nBeim Verbrauchen von Runen habt Ihr die Chance, 10 Sek. lang die Hilfe eines Reiters zu erhalten.\n\nMograine\nWirkt 'Tod und Verfall' an seiner Position. Der Effektbereich folgt seiner Bewegung.\n\nWeißsträhne\nWirkt 'Untot' auf Euer Ziel, was 24 Sek. lang alle 3 Sek. pro Stapel (9.15376% der Angriffskraft) Schattenfrostschaden verursacht. Wann immer 'Untot' Schaden verursacht, wird das Ziel mit einem weiteren Stapel belegt. Kann nicht erneuert werden.\n\nTrollbann\nWirkt 'Eisketten' auf Euer Ziel, was 8 Sek. lang dessen Bewegungsgeschwindigkeit um 40% verringert und den Schaden, den Ihr ihm zufügt, um 5% erhöht.\n\nNazgrim\nWährend Nazgrim aktiv ist, erhaltet Ihr 'Apokalyptische Eroberung', was Eure Stärke um 5% erhöht." }
entries[454393] = { ["name"] = "Mograine beschwören", ["text"] = "Sofort\nBeim Verbrauchen von Runen habt Ihr die Chance, 10 Sek. lang die Hilfe eines Reiters zu erhalten.\n\nMograine\nWirkt 'Tod und Verfall' an seiner Position. Der Effektbereich folgt seiner Bewegung.\n\nWeißsträhne\nWirkt 'Untot' auf Euer Ziel, was 24 Sek. lang alle 3 Sek. pro Stapel (9.15376% der Angriffskraft) Schattenfrostschaden verursacht. Wann immer 'Untot' Schaden verursacht, wird das Ziel mit einem weiteren Stapel belegt. Kann nicht erneuert werden.\n\nTrollbann\nWirkt 'Eisketten' auf Euer Ziel, was 8 Sek. lang dessen Bewegungsgeschwindigkeit um 40% verringert und den Schaden, den Ihr ihm zufügt, um 5% erhöht.\n\nNazgrim\nWährend Nazgrim aktiv ist, erhaltet Ihr 'Apokalyptische Eroberung', was Eure Stärke um 5% erhöht." }
