entries[454419] = { ["name"] = "Schicksal auslosen", ["text"] = "Meucheln\n'Verstümmeln', 'Hinterhalt' und 'Dolchfächer' generieren 1 zusätzlichen Combopunkt, wenn sie 'Schicksal besiegeln' auslösen.\n\nGesetzlosigkeit\n'Finsterer Stoß' generiert 1 zusätzlichen Combopunkt, wenn er ein weiteres Mal trifft." }
