entries[454421] = { ["name"] = "Schicksal auslosen", ["text"] = "Sofort\nMeucheln\n'Verstümmeln', 'Hinterhalt' und 'Dolchfächer' generieren 1 zusätzlichen Combopunkt, wenn sie 'Schicksal besiegeln' auslösen.\n\nGesetzlosigkeit\n'Finsterer Stoß' generiert 1 zusätzlichen Combopunkt, wenn er ein weiteres Mal trifft." }
entries[454426] = { ["name"] = "Unbändiges Unheil", ["text"] = "Der verursachte Schaden, wenn Eure 'Schicksalsgebundene Münze' auf Zahl landet, ist um 30% erhöht, wenn sich keine anderen Gegner in der Nähe des Ziels befinden.\n\nJeder weitere Gegner in der Nähe verringert diesen Bonus um 6%." }
entries[454428] = { ["name"] = "Schicksalhaftes Ende", ["text"] = "Wenn Eure schicksalsgebundene Münze sieben Mal hintereinander die gleiche Seite zeigt, dürft Ihr die Glücksmünze behalten. Sie gewährt Euch 7% Beweglichkeit, bis Ihr den Kampf 10 Sek. lang verlasst. Wenn Ihr bereits eine Glücksmünze habt, fügt sie Eurem Ziel stattdessen (420% der Angriffskraft) kosmischen Schaden zu." }
entries[454429] = { ["name"] = "Verbundenes Schicksal", ["text"] = "Gesetzlosigkeit\n'Verbundenes Schicksal' dupliziert 30% des kritischen Schadens von 'Tötung' als kosmischen Schaden auf 2 zusätzliche Gegner in der Nähe. Wenn es keine zusätzlichen Ziele in der Nähe gibt, werden stattdessen 30% des Schadens auf das Primärziel geleitet.\n\nMeucheln\n'Verbundenes Schicksal' dupliziert 30% des kritischen Schadens von 'Vergiften' als kosmischen Schaden auf 2 zusätzliche Gegner in der Nähe. Wenn es keine zusätzlichen Ziele in der Nähe gibt, werden stattdessen 30% des Schadens auf das Primärziel geleitet." }
entries[454430] = { ["name"] = "Doppelmord", ["text"] = "Euer erster Wurf einer schicksalsgebundenen Münze nach Aufheben der Verstohlenheit löst zwei Würfe mit garantiert demselben Ergebnis aus." }
entries[454431] = { ["name"] = "Das abgetrennte Säckchen", ["text"] = "Wirken in 2 sek. 2\nReagenzien:\nZierendes Band (2), Dämmergespinstballen (5), Morgengespinstballen (5)\nOptionale Reagenzien:\nStickereifaden (#333)\nSpezialisierung:\nHochwertiger Stoff (25)\n\nDas abgetrennte Säckchen\nWird beim Aufheben gebunden\nEinzigartig\n36 Platz Tasche\nAnlegen: Erhöht den maximalen Ertrag beim Zerfasern von Khaz Algar um 1.\n\n[ Anlegeeffekt erfordert Schneiderei von Khaz Algar 1 ][ Anlegeeffekt erfordert Schneiderei von Khaz Algar 1 ]68\n\"Ein Behälter, der von den Meisterhandwerkern der Weberin gesponnen wurde, die den Wert von so seltenem Stoff wie Morgengespinst und Dämmergespinst voll ausnutzen.\"" }
entries[454432] = { ["name"] = "Unerbittlicher Marsch", ["text"] = "Ihr könnt nicht auf weniger als 70% der normalen Bewegungsgeschwindigkeit verlangsamt werden, während Ihr eine Strähne von mindestens 2 Würfen der schicksalsgebundenen Münze mit demselben Ergebnis habt." }
entries[454433] = { ["name"] = "Ankunft des Todes", ["text"] = "Gesetzlosigkeit\n'Greifhaken' kann innerhalb von 3 Sek. ohne Abklingzeit ein zweites Mal eingesetzt werden, doch die gesamte Abklingzeit wird um 5 Sek. erhöht.\n\nMeucheln\n'Schattenschritt' kann innerhalb von 3 Sek. ohne Abklingzeit ein zweites Mal eingesetzt werden, doch die gesamte Abklingzeit wird um 5 Sek. erhöht." }
entries[454434] = { ["name"] = "Unausweichliches Ende", ["text"] = "Gesetzlosigkeit\nDie nächsten zwei Fähigkeiten profitieren jetzt von 'Kaltblütigkeit', allerdings nur 'Tötung'. 'Schicksalsgebundene Münzen', die von diesen Fähigkeiten geworfen werden, erzielen garantiert das gleiche Ergebnis, auf dem sie auch beim letzten Wurf gelandet sind.\n\nMeucheln\nDie nächsten zwei Fähigkeiten profitieren jetzt von 'Kaltblütigkeit', allerdings nur 'Vergiften'. 'Schicksalsgebundene Münzen', die von diesen Fähigkeiten geworfen werden, erzielen garantiert das gleiche Ergebnis, auf dem sie auch beim letzten Wurf gelandet sind." }
entries[454435] = { ["name"] = "Schicksalsbestimmt", ["text"] = "Gesetzlosigkeit\n'Finsterer Stoß' hat eine 5% höhere Chance, ein zusätzliches Mal zuzuschlagen, und Eure schicksalsgebundenen Münzen haben bei einem Wurf eine 5% höhere Chance, dieselbe Seite zu zeigen wie beim letzten Wurf.\n\nMeucheln\nWaffengifte haben eine 5% höhere Chance, angewendet zu werden, und Eure schicksalsgebundenen Münzen haben bei einem Wurf eine 5% höhere Chance, dieselbe Seite zu zeigen wie beim letzten Wurf." }
entries[454436] = { ["name"] = "Trampeln", ["text"] = "100 Meter Reichweite\nSofort\nStürmt auf einen zufälligen Gegner zu und fügt allen Spielercharakteren in seinem Weg 11025 Schattenschaden zu. Getroffene Ziele werden für 10 Sek. betäubt." }
entries[454437] = { ["name"] = "Azeritsprengladung", ["text"] = "Sofort\nZiel von Azeritsprengladung!" }
entries[454438] = { ["name"] = "Azeritsprengladung", ["text"] = "100 Meter Reichweite\nWirken in 3 sek.\nStürmt auf einen anvisierten Gegner zu und verursacht eine Explosion von Azeritenergie, die allen Gegnern innerhalb von 8 Metern um den Einschlag 4134 Arkanschaden und 5 Sek. lang alle 1 Sek. 1102 zusätzlichen Arkanschaden zufügt." }
entries[454439] = { ["name"] = "Azeritsprengladung", ["text"] = "100 Meter Reichweite\nSofort\nStürmt auf einen anvisierten Gegner zu und verursacht eine Explosion von Azeritenergie, die allen Gegnern innerhalb von 8 Metern um den Einschlag 4134 Arkanschaden und 5 Sek. lang alle 1 Sek. 1102 zusätzlichen Arkanschaden zufügt." }
entries[454440] = { ["name"] = "Stinkendes Erbrochenes", ["text"] = "100 Meter Reichweite\nWirken in 2 sek.\nFügt Zielgegnern 1654 Naturschaden sowie zusätzlich 12 Sek. lang alle 2 Sek. 1102 Naturschaden zu." }
entries[454441] = { ["name"] = "Algarischer Angler werden", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nAngler werden ist nicht schwer!\n\nWerft Eure Leine aus und holt die zahlreichen Geheimnisse hervor, die in Khaz Algar schlummern.\n\nIn Eurem treuen Angeltagebuch werden gefangene Fische und Fischschwärme festgehalten. Die Aufzeichnungen geben Aufschluss über die feinen Fische und wo Ihr sie womöglich findet!\nBeruf:\nAngeln (1)" }
entries[454442] = { ["name"] = "Angelfertigkeit und Ihr", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nWenn sich Eure Fähigkeit, den perfekten Fang einzuholen, verbessert, erhöht sich auch Eure Angelfertigkeit!\n\nEure Angelfertigkeiten soweit zu verbessern, wie Ihr imstande seid, macht den Unterschied, ob Ihr einen alten Stiefel oder einen kostbaren Trophäenfisch aus dem Wasser zieht.\nBeruf:\nAngeln (25)" }
entries[454443] = { ["name"] = "Stiller Flussbarsch", ["text"] = "Sofort\nSchimmernde Smaragdschuppen zieren diesen ansonsten unauffälligen Fisch. Mit seinem reichhaltigen und feinen Aroma ist der stille Flussbarsch eine gern verwendete Zutat in jedem Meeresfrüchtegericht.\n\nBesondere Verwendung:\n\nFrisches Filet\n\nDie Verwertung dieses Fisches mit der Kochfertigkeit kann eine mäßige Menge frisches Filet hervorbringen.\n\nVerbreitungsgebiete:\n\n- Insel von Dorn\n- Schallende Tiefen\n- Sireneninsel\n\nFischschwärme:\n\n- Ruhige Oberflächenwellen\n- Flussbarschteich\nBeruf:\nAngeln" }
