entries[454454] = { ["name"] = "Schuldumleitungsgerät", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie Tüftelei eines anderen Spielercharakters hat eine Fehlfunktion erlitten. Das Schuldumleitungsgerät hat dafür gesorgt, dass jemand anderes an den Konsequenzen leidet." }
entries[454455] = { ["name"] = "Komplizierter Sicherungskasten", ["text"] = "Sofort\nWenn die Tüftelei, die in diesem Gerät eingesetzt ist, eine Fehlfunktion erleidet, wird eine Sicherung ausgelöst, um Gefahren zu vermeiden." }
