entries[454472] = { ["name"] = "Klaffende Raserei", ["text"] = "20 Meter Reichweite\nSofort\nKlaffzahn schattenschreitet fünfmal schnell zwischen den Spielercharakteren hin und her und verursacht 3636674 körperlichen Schaden. Getroffene Spielercharaktere bluten 15 Sek. lang alle 1.5 Sek. für 646528 körperlichen Schaden." }
