entries[454747] = { ["name"] = "Alarmgeschütz 2000", ["text"] = "Für den folgenden Effekt in einen Tüfteleisockel einsetzen:\n\nAlarmgeschütz 2000\nPlatziert ein verborgenes Alarmgeschütz 2000 an einer Zielposition in der Nähe. Falls ein gegnerischer Spielercharakter dessen Entdeckungsradius betritt, macht es Euch auf diesen aufmerksam und versucht 30 Sek. lang, oder bis es zerstört wird, den Bereich zu verteidigen." }
