entries[454749] = { ["name"] = "Teilchenbeschleuniger 2000", ["text"] = "Für den folgenden Effekt in einen Tüfteleisockel einsetzen:\n\nTeilchenbeschleuniger 2000\nFixiert einen bis zu 12 bis 60 Meter entfernten Gegner als Ziel. Wenn Euer Weg nach 1.5 Sek. frei von Hindernissen bleibt, stürmt Ihr mit Schallgeschwindigkeit vorwärts. Wenn es zur Kollision kommt, werdet Ihr und das Ziel für 1.5 Sek. betäubt." }
entries[454750] = { ["name"] = "Schattenflammenraketen", ["text"] = "Für den folgenden Effekt in einen Tüfteleisockel einsetzen:\n\nSchattenflammenraketen\nSpringt auf ein Holzbrett, an das willkürlich Schattenflammenraketen genagelt wurde. Da kann gar nichts schiefgehen, aber wenn doch, würde das 526287 Schattenflammenschaden verursachen, die zwischen Euch und allen Gegnern aufgeteilt würden, die von der theoretischen Explosion getroffen werden." }
