entries[454857] = { ["name"] = "Lebhaftigkeit", ["text"] = "30 Meter Reichweite\nEure schädlichen Zauber und Fähigkeiten haben eine Chance, 'Lebhaftigkeit' zu gewähren. Erhöht Sekundärwerte um 490 und Geschwindigkeit bzw. Vermeidung um 182 je nach Art der Aktivierung." }
entries[454859] = { ["name"] = "Lebhaftigkeit", ["text"] = "Sofort\nCa. 2 Procs pro Minute\nEure schädlichen Zauber und Fähigkeiten haben eine Chance, Euer Ziel 15 Sek. lang mit 'Strahlender Fokus' zu entzünden.\n\nNachdem die fokussierten Energien dem Ziel bis zu 1910683 Schaden zugefügt haben, entzünden sie Euch mit Strahlung und erhöhen Euren höchsten Sekundärwert abhängig vom verursachten Schaden 15 Sek. lang um einen Wert zwischen ( 782 * .5) und 782 ." }
