entries[455284] = { ["name"] = "Infizierte Ausgeburt", ["text"] = "Unbegrenzte Reichweite\nSofort\nRasha'nan pflanzt in den markierten Zielen eine neue Brut, die Spielercharakteren innerhalb von 5 Metern 3367445 Naturschaden zufügt . Diese belegen den Wirt mit ' Infizierter Biss ', bevor sie sich eine neue Beute sucht." }
entries[455287] = { ["name"] = "Infizierter Biss", ["text"] = "Unbegrenzte Reichweite\nWirken in 0.5 sek.\nDie infizierte Ausgeburt kaut auf ihrem Ziel herum, was alle 1 Sek. 543972 Naturschaden verursacht und die Bewegungsgeschwindigkeit um 5% verringert. Hält 6 Sek. lang an. Dieser Effekt ist stapelbar." }
