entries[455289] = { ["name"] = "Essen", ["text"] = "Sofort\nStellt im Verlauf von 20 Sek. ( 80357 / 5 * 20) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet den Effekt 'Süße Eklipse', wodurch jeder in den Schatten getötete Gegner Eure kritische Trefferchance um 3% erhöht.\n\nVerwendbar in Blüte des Lichts und nahen Schlüsselflammengebieten." }
entries[455290] = { ["name"] = "Süße Eklipse", ["text"] = "Sofort\nDas Töten einer Kreatur in den Schatten gewährt Euch 30 Sek. lang eine Erhöhung der kritischen Trefferchance um 3%. Dieser Effekt ist bis zu 10-mal stapelbar. Hält 1 Stunde lang an.\n\nLeuchtende Resilienz unterdrückt diesen Effekt.\n\nVerwendbar in Blüte des Lichts und nahen Schlüsselflammengebieten." }
entries[455291] = { ["name"] = "Uraltes Konstrukt", ["text"] = "20 Meter Reichweite\nSofort 1 Stunde Abklingzeit\nBeschwört am Zielort Ikarus, den Unzerbrechlichen, der 1 Min. lang bestehen bleibt. Dieser dient als Zielattrappe und kann von der jeweils entgegengesetzten Rolle geheilt werden oder Schaden durch sie erleiden, solange sie bestehen bleibt. Wie weit könnt Ihr die Zahlen steigen lassen?\n\nKann nur im Freien eingesetzt werden." }
