entries[455328] = { ["name"] = "Aufgedeckte Chaosmine", ["text"] = "Unbegrenzte Reichweite\nSofort\nWenn Ihr Schaden erleidet und Eure Gesundheit unter 40% Eurer maximalen Gesundheit fällt, verteilt Ihr 8 Sek. lang zufällig 6 Minen um Euch herum. Gegner, die auf diese Minen treten, erleiden ( 1 * 1982 ) Feuerschaden und werden 4 Sek. lang um 70% verlangsamt.\n\nEin Gegner kann nur 1 Mine pro Notfall auslösen. Kann nur einmal alle 2 Min. vorkommen." }
