entries[455334] = { ["name"] = "Läuternde Flammen", ["text"] = "Wirken in 2 sek.\nAscheron kanalisiert heftige Flammen, um Eindringlinge zu beseitigen. Tödliche Feuerstrahlen drehen sich in der Kammer und fügen Spielercharakteren bei Berührung 14546696 Feuerschaden zu." }
