entries[455392] = { ["name"] = "Symbiose", ["text"] = "Wirken in 3 sek.\nReagenzien:\nAss der Symbiose , Zwei der Symbiose , Drei der Symbiose , Vier der Symbiose , Fünf der Symbiose , Sechs der Symbiose , Sieben der Symbiose , Acht der Symbiose\nVereint alle Karten vom Ass bis zur Acht der Symbiose, um das Set zu vervollständigen." }
