entries[455394] = { ["name"] = "Aszendenz", ["text"] = "Wirken in 3 sek.\nReagenzien:\nAss der Aszendenz , Zwei der Aszendenz , Drei der Aszendenz , Vier der Aszendenz , Fünf der Aszendenz , Sechs der Aszendenz , Sieben der Aszendenz , Acht der Aszendenz\nVereint alle Karten vom Ass bis zur Acht der Aszendenz, um das Set zu vervollständigen." }
entries[455395] = { ["name"] = "Monstrosität erwecken", ["text"] = "1 Rune / -10 Runenmacht 40 Meter Reichweite\nSofort 1.5 min Abklingzeit\nLässt für 30 Sek. eine Monstrosität auferstehen, die umherstreift und Gegner angreift. Sie belegt Ziele durch ihre Nahkampfangriffe mit 'Schwärende Wunde' und Ziele in ihrer Nähe mit 'Virulente Seuche'." }
entries[455396] = { ["name"] = "Faulende Infektionen", ["text"] = "Eure Krankheiten verursachen 10% mehr Schaden und haben eine 5% höhere Chance auf kritische Treffer." }
entries[455397] = { ["name"] = "Schwärende Sense", ["text"] = "Jeder 20. Einsatz von 'Schwärende Wunden' bewirkt, dass Euer nächster 'Schwärender Stoß' zu 'Schwärende Sense' wird.\n\nSchwärende Sense\nFegt durch alle Gegner innerhalb von 14 Metern vor Euch, fügt ihnen (200% der Angriffskraft) Schattenschaden zu und infiziert sie mit 2 bis 3 Stapeln von 'Schwärende Wunde'." }
entries[455398] = { ["name"] = "Verrottung", ["text"] = "'Virulente Seuche' hat eine Chance, plötzlich zu entbrennen und dem Ziel 50% des Schadens zuzufügen, den sie ihm in den letzten 4 Sek. verursacht hat.\n\nBei Auslösung dieses Effekts wird die Dauer Eurer aktiven Diener um 1.0 Sek. verlängert, bis zu einem Maximum von 3.0 Sek." }
entries[455399] = { ["name"] = "Walzende Säure", ["text"] = "Unbegrenzte Reichweite\nSofort\nRasha'nan stößt ein giftiges Gebräu auf markierte Ziele aus, das in Wellen vom Ziel aus in die angegebene Richtung schwappt.\n\nSpielercharaktere, die von der anfänglichen ätzenden Eruption bespritzt werden, erleiden ' Ätzende Benommenheit '.\n\nJeder Spielercharakter, der eine Welle berührt, wird um 50% verlangsamt und wird alle 1 Sek. mit ' Korrosion ' belegt.\n\nDie Wellen verbrennen ' Klebrige Netze ', fügen Spielcharakteren im Umkreis von 5 Metern 1726895 Naturschaden zu und erzeugen ' Säurepfützen '." }
entries[455400] = { ["name"] = "Kampfrausch", ["text"] = "40 Meter Reichweite\nSofort\nTempo um 15% und Bewegungsgeschwindigkeit um 15% erhöht." }
