entries[455404] = { ["name"] = "Festmahl", ["text"] = "Unbegrenzte Reichweite\nSofort\nAnsurek labt sich an einem Stück Fleisch ihres aktuellen Ziels, was diesem 43172364 körperlichen Schaden zufügt und die nächsten 34351412 Heilung absorbiert.\n\nDie Wunde absorbiert zusätzliche Heilung in Höhe von 100% des verursachten körperlichen Schadens." }
