entries[455416] = { ["name"] = "Abyssischer Nachhall", ["text"] = "Unbegrenzte Reichweite\nSofort\nAnsurek belegt Spielercharaktere mit dunkler Energie und fügt ihnen innerhalb von 10 Metern 6 Sek. lang alle 1 Sek. 1439079 Schattenschaden zu.\n\nBei Ablauf bricht die Energie in eine ' Abyssalleitung ' auf und fügt Spielercharakteren innerhalb von 10 Metern 2014710 Schattenschaden zu und stößt sie zurück." }
entries[455419] = { ["name"] = "Schwindende Kerze des Höhlenforschers", ["text"] = "Ca. 2 Procs pro Minute\nEure schädlichen Zauber und Fähigkeiten haben eine Chance, dass eine Kerze des Höhlenforschers auf Eurem Kopf platziert wird, die Euch 15 Sek. lang einen kritischen Trefferwert von 128 gewährt.\n\nWenn Ihr Euch einem Verbündeten bis auf 3 Meter annähert, wird auch ihm eine Kerze des Höhlenforschers gewährt und Ihr profitiert für die verbleibende Dauer beide vom Effekt." }
entries[455420] = { ["name"] = "Kerze des Höhlenforschers", ["text"] = "Sofort\nEure schädlichen Zauber und Fähigkeiten haben eine Chance, dass eine Kerze des Höhlenforschers auf Eurem Kopf platziert wird, die Euch 15 Sek. lang einen kritischen Trefferwert von 128 gewährt.\n\nWenn Ihr Euch einem Verbündeten bis auf 3 Meter annähert, wird auch ihm eine Kerze des Höhlenforschers gewährt und Ihr profitiert für die verbleibende Dauer beide vom Effekt." }
