entries[455484] = { ["name"] = "Abnehmbarer Zahn", ["text"] = "Ca. 6 Procs pro Minute\nEure schädlichen Nahkampffähigkeiten haben eine Chance, 'Knirscher' auf Euer Ziel anzuwenden und ihm ( 1 * 387 ) körperlichen Schaden zuzufügen. Jede dritte Anwendung von 'Knirscher' auf dasselbe Ziels verursacht zusätzlichen Schaden basierend auf der fehlenden Gesundheit des Ziels. Wenn 'Knirscher' ein anderes Ziel trifft, wird der Zähler zurückgesetzt." }
