entries[455511] = { ["name"] = "Lebloses Relikt der Nekrotischen Fäulnis", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer Götze benutzt unheilige Energie, um tödlichen Schaden bei Spielercharakteren zu verhindern und heilt sie stattdessen um einen Betrag, der 100% ihrer maximalen Gesundheit entspricht, und verwandelt sie in Untote.\n\nSolange sie untot sind, können sie nicht geheilt werden, verlieren alle 1 Sek. 14% ihrer maximalen Gesundheit, und ihr Schaden und ihre Heilung ist um 6% erhöht." }
